base_dir = '/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/held-out-2/play/users/u026/system/state/workspace/programs'

# Search all files for this task ID
print(f"Searching for {task_id} in {base_dir}...")
for root, dirs, files in os.walk(base_dir):
    # Skip infinite recursion
    try:
        files.sort()
    except:
        pass
    for f in files:
        if f.endswith('.json') or f.endswith('.py'):
            fpath = os.path.join(root, f)
            try:
                with open(fpath, 'r') as fin:
                    content = fin.read()
                    if task_id in content:
                        print(f"Found {fpath}")
                        print(f"  First 200 chars: {content[:200]}")
            except Exception as e:
                print(f"  Error reading {fpath}: {e}")

